// пин, к которому подключен светодиод
int ledPin = 13;

void setup() {
  // настраиваем пин как выход
  pinMode(ledPin, OUTPUT);
}

void loop() {
  digitalWrite(ledPin, HIGH);  // включаем светодиод
  delay(1000);                 // ждём 1 секунду
  digitalWrite(ledPin, LOW);   // выключаем светодиод
  delay(1000);                 // ждём 1 секунду
}
